CREATE OR REPLACE FUNCTION "demo_pkg_найти_товар" (p_ident bigint) RETURNS bigint AS $body$
DECLARE

      res   bigint := NULL;

BEGIN
      SELECT MIN(op.товар)
        INTO STRICT res
        FROM товар op, товар op2
       WHERE op.партия = op2.партия
         AND op2.товар = p_ident;

      RETURN res;
   END;
$body$
LANGUAGE PLPGSQL
;
